sys_script_include.script:
var IncidentPayload2 = Class.create();
IncidentPayload2.prototype = {
    initialize: function() {},

    createIncidentPayload: function(incident_sys_id) {
        // Read system property (comma-separated field names)
        var fieldsProp = gs.getProperty('x_1319705_servicen.Incident.fields');
        var fields = fieldsProp.split(',');

        var incidentValues = {};
		var incidentSysId = incident_sys_id;
        var incidentRec = new GlideRecord('incident');
        incidentRec.get(incidentSysId);

        fields.forEach(function(field) {
            var value = incidentRec.getDisplayValue(field);
            if (value) {
                if (field == 'number') {
                    incidentValues.correlation_id = value;
                } else {
                    incidentValues[field] = value;
                }
            }
        });

        return incidentValues;
    },


    type: 'IncidentPayload2'
};
